  // ═══════════════════════════════════════════════════════════════════════════════════════════════
  //  IC FOR SQUIGGY — the house rules, numbered, so a small model can CITE instead of freestyle.
  //
  //  WHY THIS FILE EXISTS: the sweep asks squiggy for "[TASTE|L340|#8]" — a rule number. It was
  //  asking a model to cite rules it had never been handed. This is the hand.
  //
  //  ⚠ THE NUMBERS ARE LAW. APPEND ONLY. NEVER RENUMBER.
  //     A sweep written to sweeps/*.md last week cites #8. Renumber and every past sweep lies.
  //     #8 is also cited in code (the rgba check). New rule? Add it at the END with the next number.
  //
  //  TWO KINDS OF RULE, and the split is the whole design:
  //    re / test  →  MECHANICAL. a regex or a line predicate. runs FREE in rung 1. facts.
  //    (neither)  →  JUDGMENT. no check possible. rides in the prompt for the model to weigh.
  //  Facts belong in lookups; judgment belongs in models. Every rule we can mechanize is one
  //  fewer thing a 3B model can be wrong about.
  //
  //  ada:1 marks a rule that is an ACCESS defect, not a taste call. Those run second, right after
  //  "does it parse" — Sum's order: "will it compile, then can a disabled person use it."
  //
  //  The human-readable view is generated from this table, never hand-written:
  //    node ~/Local/0z-desk/ic-for-squiggy.js   →   ~/Local/intelligence-coding/IC-FOR-SQUIGGY.md
  //  One source, two surfaces. The doc can't drift from what the app actually checks.
  // ═══════════════════════════════════════════════════════════════════════════════════════════════
  const IC_RULES = [
    { n: 1, rule: 'one concern per file — build under 500 lines, ship under 1080.' },
    { n: 2, rule: 'a blank line between a comment and the code it describes. always.' },
    { n: 3, rule: 'name into a prefix family — fire* leaves, set* writes, make* returns, *Poll listens.' },
    { n: 4, rule: 'a value used twice lives in tokens.css — write var(--space-md), not 12px.' },
    { n: 5, rule: 'never !important — the real bug is specificity, inheritance, or the wrong token.', re: /!important/ },
    { n: 6, rule: 'every control has a name — visible text or aria-label.', ada: 1, re: /<button(?![^>]*aria-label)[^>]*>\s*(?:<[^>]*>\s*)*<\/button>/i, why: 'a button with no text and no aria-label — Voice Control cannot name it' },
    { n: 7, rule: 'no onclick on a div or span — use a real button.', ada: 1, re: /<(?:div|span)[^>]*onclick=/i, why: 'no keyboard path, no role — unreachable by switch or voice' },
    { n: 8, rule: 'solid hex on text — never rgba(), never opacity on text.', ada: 1, re: /color\s*:\s*rgba\(/i, why: 'rgba on text renders washed out and fails contrast' },
    { n: 9, rule: 'a button has mass — background + box-shadow, not transparent + a 1px border.' },
    { n: 10, rule: 'symbols over labels — a label earns its place by resolving ambiguity.' },
    { n: 11, rule: 'an input carries aria-label or placeholder.', ada: 1, re: /<input(?![^>]*(?:aria-label|placeholder))[^>]*>/i, why: 'unnamed to a screen reader' },
    { n: 12, rule: 'share DATA, never runtime — no window.parent.* across a card wall.', re: /window\.parent\./ },
    { n: 13, rule: 'a folder reaches across no wall — it carries everything it needs.' },
    { n: 14, rule: 'move the view, not the content — never display:none to swap a page.' },
    { n: 15, rule: 'a line starting with [ or ( gets a leading ; — the no-semicolon trap.', test: (l, p) => /^\s*[[(]/.test(l) && /[\w\])'"`]\s*$/.test(p || ''), why: 'JS reads this as an index or a call on the line above' },
    { n: 16, rule: 'set color on the container, never the leaf — the next leaf inherits wrong.' },
    { n: 17, rule: 'mv, never rm — recover beats regret.', re: /\brm\s+-[rf]/ },
    { n: 18, rule: 'typed it twice? extract a factory.' },
    { n: 19, rule: 'everything the user configured lives in localStorage. wifi changes; the app must not break.' },
    { n: 20, rule: 'console.log is ship-pass only — mid-build noise creates false leads.', re: /console\.log\(/ },
    { n: 21, rule: '80 chars of content per line, 100 hard. UI copy: 40 target, 50 max.', test: l => l.length > 100, why: 'past 100 chars the nesting wants restructuring, not wrapping' },
    { n: 22, rule: 'stanza, never prose — one idea, short lines, a blank line between.' },
    { n: 23, rule: 'the TOC is copied from the // -- dividers in the body. never invented.' },
    { n: 24, rule: 'no will-change:transform — it paints over position:fixed and eats the nav.', re: /will-change\s*:\s*transform/ },
    { n: 25, rule: 'display:none plus flex-basis is broken — restructure, do not fight it.' },
    { n: 26, rule: 'no emoji in a shipped surface — draw the glyph as svg. codepoints do not port.' },
    { n: 27, rule: 'no platform-only API — std and the sealed crates only, or it can never be a bean.' },
    { n: 28, rule: 'each section carries a FOR HUMANS block and a FOR AI block.' },
    { n: 29, rule: 'three strikes in one file, then stop — new file, one concern, port it back.' },
    { n: 30, rule: 'do not integrate before it works in isolation. prototype, works, port. that order.' },
    { n: 31, rule: 'the closing line earns its place or it does not ship.' },
    { n: 32, rule: 'delete every line that is not the idea — then breathe between the ones that are.' }
  ]

  // the compact card that rides in the sweep prompt. ONE line per rule, so a 3B model
  // can hold all 32 and still have room to read the file it is reviewing.
  function icCard() { return IC_RULES.map(r => '#' + r.n + ' ' + r.rule).join('\n') }

  // ── the mechanical runner. ONE rule = ONE finding, however many times it hits ──────────────────
  //    200 rgba lines is not 200 findings, it is one finding with 200 addresses. Reported as one
  //    (so the list stays walkable) but CARRYING every line (so FIX ALL can patch them in one press).
  //    Sum: "fix all if 200 of same mistake." Walking 200 identical steps is punishment, not review.
  function icScan(rule, lines) {
    const hits = []
    for (let i = 0; i < lines.length; i++) {
      if (rule.re ? rule.re.test(lines[i]) : rule.test(lines[i], lines[i - 1])) hits.push(i + 1)
    }
    if (!hits.length) return null
    const tail = hits.length > 1 ? ` (${hits.length} places)` : ''
    return { kind: 'VERIFIED', line: hits[0], rule: String(rule.n), hits, why: (rule.ada ? 'ADA — ' : '') + (rule.why || rule.rule) + tail }
  }

  window.IC_RULES = IC_RULES
  window.IC_CARD = icCard
